head.script:
scwin.onpageload = function() {
    result.setValue(sc1.getView()['type']);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    result.setValue(sc1.getView()['type']);
};
scwin.trigger2_onclick = function(e) {
    sc1.changeView('dayGridMonth');
};
scwin.trigger3_onclick = function(e) {
    sc1.changeView('dayGridWeek');
};
scwin.trigger4_onclick = function(e) {
    sc1.changeView('dayGridDay');
};
scwin.check_changeView = function(param) {
    var selected = param;
    return WebSquare.wUnit.getDomById('sc1').querySelectorAll('button')[selected].classList.contains('fc-button-active');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('result').innerText == 'dayGridMonth'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.check_changeView(3)", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.check_changeView(4)", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.check_changeView(5)", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
